from __future__ import annotations

from typing import Any

from pathxai_agent.evaluation.pathology_metrics import pathology_report_score
from pathxai_agent.evaluation.reference_cleaner import rule_based_image_only
from pathxai_agent.evaluation.report_text_metrics import (
    bleu,
    compact_metric_summary,
    extract_sections,
    report_similarity,
    rouge_n_score,
    text_semantic_similarity,
    tokenize,
)


def _compute_ref_metrics(
    generated_report: str,
    reference_text: str,
    site_text: str,
    diagnosis_text: str,
    label: str,
    description: str,
) -> dict[str, Any]:
    """Compute a full evaluation block for one reference version (V1 or V2)."""
    secs = extract_sections(reference_text)
    ref_site = secs.get("Specimen/Site", "")
    ref_diagnosis = secs.get("Diagnosis", "")
    pred_secs = extract_sections(generated_report)
    _ALL_SECTIONS = [
        "Specimen/Site", "Diagnosis", "Tumor/Lesion Description",
        "Key Microscopic Findings", "Invasion/Necrosis/Margins",
        "Immunohistochemistry/Ancillary Studies",
        "Stage/Grade/Prognostic Features", "Final Summary",
    ]
    _SKIP_REF_VALUES = {"Not assessable from H&E images.", "Not specified.", ""}
    sec_sims: dict[str, float] = {}
    sec_details: dict[str, dict] = {}
    for s in _ALL_SECTIONS:
        ref_s = secs.get(s, "")
        pred_s = pred_secs.get(s, "")
        if not ref_s or ref_s in _SKIP_REF_VALUES:
            continue
        sim = text_semantic_similarity(pred_s, ref_s)["semantic_similarity"]
        sec_sims[s] = sim
        sec_details[s] = {
            "similarity": sim,
            "prediction": pred_s,
            "reference": ref_s,
        }

    rpt = report_similarity(generated_report, reference_text, report_style="long")
    bleu_scores = bleu(generated_report, reference_text)
    return {
        "label": label,
        "description": description,
        "ref_site": ref_site,
        "ref_diagnosis": ref_diagnosis,
        "site_similarity": text_semantic_similarity(site_text, ref_site)["semantic_similarity"],
        "diagnosis_similarity": text_semantic_similarity(diagnosis_text, ref_diagnosis)["semantic_similarity"],
        "report_quality_score": compact_metric_summary(rpt).get("report_quality_score"),
        "bleu_1": bleu_scores.get("bleu_1"),
        "rouge_1": rouge_n_score(generated_report, reference_text, n=1)["f1"],
        "rouge_2": rouge_n_score(generated_report, reference_text, n=2)["f1"],
        "section_similarities": sec_sims,
        "section_details": sec_details,
    }


def staged_prediction_metrics(
    staged_payload: dict[str, Any],
    reference_report: str | None,
    reference_full_structured: str | None = None,
    reference_image_only: str | None = None,
) -> dict[str, Any]:
    """Evaluate staged intermediate predictions separately from final report.

    Parameters
    ----------
    staged_payload:
        Output of ``run_staged_report_agent*()`` – the full staged_trace dict.
    reference_report:
        Raw or existing cleaned GT report text (used for legacy metrics).
    reference_full_structured:
        LLM-structured reference with ALL clinical information preserved (V1).
        Generated by ``scripts/generate_structured_references.py``.
    reference_image_only:
        LLM-structured reference with only H&E-image-observable content (V2).
        Generated by ``scripts/generate_structured_references.py``.
    """
    if not reference_report:
        return {
            "available": False,
            "reason": "missing reference report",
        }
    sections = extract_sections(reference_report)
    # Use image-only cleaned site (drop procedure/surgical details like
    # "resection", "lymph node" etc.) so the comparison is tissue-type → tissue-type.
    ref_site = _image_only_site(sections.get("Specimen/Site", ""))
    ref_diagnosis = sections.get("Diagnosis", "")

    # Detect unstructured reference (e.g. raw OCR without section headers)
    _ref_has_sections = bool(sections)
    _ref_parse_warning: str | None = None
    if not _ref_has_sections and len(reference_report.strip()) > 50:
        _ref_parse_warning = (
            "Reference report could not be parsed into structured sections "
            "(no expected section headers found). The raw text may be OCR output "
            "without structure. Section-level similarities will be 0. "
            "Run generate_image_only_references.py to produce a structured version."
        )

    site_payload = staged_payload.get("site_prediction") or {}
    diagnosis_payload = staged_payload.get("diagnosis_prediction") or {}
    generated_report = staged_payload.get("generated_long_report") or ""

    site_text = str(site_payload.get("predicted_site") or "")
    # Keep primary diagnosis and differential diagnosis strictly separate.
    # Earlier versions appended the differential list here, which penalized a
    # correct primary diagnosis when broad mimics were appropriately listed.
    diagnosis_text = str(diagnosis_payload.get("primary_diagnosis") or "")
    differential_text = " ".join(str(x) for x in diagnosis_payload.get("differential") or [])
    site_similarity = text_semantic_similarity(site_text, ref_site)
    diagnosis_similarity = text_semantic_similarity(diagnosis_text, ref_diagnosis)
    report_detail = report_similarity(generated_report, reference_report, report_style="long")
    image_only = image_only_core_metrics(
        generated_report=generated_report,
        reference_report=reference_report,
        site_prediction=site_text,
        diagnosis_prediction=diagnosis_text,
    )
    path_score = pathology_report_score(generated_report, reference_report)

    # ── Image-only reference metrics ──────────────────────────────────────────
    # The clinical GT report contains gross dimensions, IHC results, TNM stage
    # etc. that are invisible in H&E WSI images.  We apply rule-based cleaning
    # to the reference to keep only image-observable content, then re-compute
    # standard NLP metrics against this cleaned reference.
    # This gives a fairer comparison for image-only generation systems.
    cleaned_ref_sections = rule_based_image_only(reference_report)
    cleaned_ref_text = cleaned_ref_sections.get("__full_text__", "")
    image_only_ref_metrics: dict[str, Any] = {
        "note": (
            "Metrics computed against a rule-based image-only cleaned version of the "
            "reference.  Gross measurements, IHC results, TNM stage, and administrative "
            "notes are removed; sections with no image-observable content are set to "
            "'Not assessable from H&E images.' so they do not penalise the model."
        ),
        "comparable_sections": cleaned_ref_sections.get("__comparable__", ""),
    }
    if cleaned_ref_text and generated_report:
        _KEY_SECTIONS = [
            "Specimen/Site", "Diagnosis", "Tumor/Lesion Description",
            "Key Microscopic Findings", "Invasion/Necrosis/Margins", "Final Summary",
        ]
        _pred_secs = extract_sections(generated_report)
        # Only include sections where the cleaned reference has actual content
        _sec_sims = {}
        for s in _KEY_SECTIONS:
            cleaned_s = cleaned_ref_sections.get(s, "")
            if not cleaned_s or cleaned_s == "Not assessable from H&E images.":
                continue
            _sec_sims[s] = text_semantic_similarity(
                _pred_secs.get(s, ""), cleaned_s
            )["semantic_similarity"]
        image_only_ref_metrics.update({
            "bleu_1": bleu(generated_report, cleaned_ref_text).get("bleu_1"),
            "bleu_2": bleu(generated_report, cleaned_ref_text).get("bleu_2"),
            "bleu_4": bleu(generated_report, cleaned_ref_text).get("bleu_4"),
            "rouge_1": rouge_n_score(generated_report, cleaned_ref_text, n=1)["f1"],
            "rouge_2": rouge_n_score(generated_report, cleaned_ref_text, n=2)["f1"],
            "section_similarities": _sec_sims,
        })

    result: dict[str, Any] = {
        "available": True,
        "evaluation_note": (
            "Full-report metrics compare against the cleaned pathology report and may include gross/IHC/stage/margin facts "
            "that are not inferable from WSI ROI images. image_only_core is the fairer primary metric for image-only runs. "
            "v1_metrics (all-info structured) and v2_metrics (image-only structured) are the primary fair metrics "
            "once structured references have been generated by scripts/generate_structured_references.py."
        ),
        "site_prediction": {
            "prediction": site_text,
            "reference": ref_site,
            "similarity": site_similarity,
            "confidence": site_payload.get("confidence"),
        },
        "diagnosis_prediction": {
            "prediction": diagnosis_text,
            "reference": ref_diagnosis,
            "similarity": diagnosis_similarity,
            "confidence": diagnosis_payload.get("confidence"),
            "differential_prediction": differential_text,
        },
        "report": {
            "metrics": compact_metric_summary(report_detail),
            "metrics_detail": report_detail,
        },
        "image_only_core": image_only,
        "image_only_ref_metrics": image_only_ref_metrics,
        "pathology_metrics": path_score,
    }

    # ── V1: LLM-structured reference with ALL clinical information ────────────
    if reference_full_structured and reference_full_structured.strip():
        result["v1_metrics"] = _compute_ref_metrics(
            generated_report=generated_report,
            reference_text=reference_full_structured,
            site_text=site_text,
            diagnosis_text=diagnosis_text,
            label="full_structured",
            description=(
                "Metrics against the LLM-structured reference that preserves ALL clinical "
                "information (gross descriptions, IHC, TNM, measurements) in a uniform "
                "8-section format.  Use this to evaluate overall report completeness."
            ),
        )

    # ── V2: LLM-structured reference with only image-observable content ───────
    if reference_image_only and reference_image_only.strip():
        result["v2_metrics"] = _compute_ref_metrics(
            generated_report=generated_report,
            reference_text=reference_image_only,
            site_text=site_text,
            diagnosis_text=diagnosis_text,
            label="image_only_structured",
            description=(
                "Metrics against the LLM-structured reference filtered to only content "
                "directly observable from H&E WSI images (gross info, IHC, TNM staging "
                "removed).  This is the fairest metric for image-only generation systems."
            ),
        )

    v2_metrics = result.get("v2_metrics") or {}
    result["primary_metrics"] = {
        "metric_version": "image_only_primary_v1",
        "primary_score": (
            v2_metrics.get("report_quality_score")
            if isinstance(v2_metrics.get("report_quality_score"), (int, float))
            else image_only.get("core_score")
        ),
        "image_only_core_score": image_only.get("core_score"),
        "image_only_structured_score": v2_metrics.get("report_quality_score"),
        "image_only_structured_diagnosis_similarity": v2_metrics.get("diagnosis_similarity"),
        "pathology_report_score": path_score.get("pathology_report_score"),
        "full_report_quality_score": compact_metric_summary(report_detail).get("report_quality_score"),
        "note": (
            "Use primary_score/image_only_core_score for WSI-only report generation. "
            "full_report_quality_score is secondary because full references may contain gross, IHC, stage, and clinical facts."
        ),
    }

    if _ref_parse_warning:
        result["reference_parse_warning"] = _ref_parse_warning
    return result


def image_only_core_metrics(
    generated_report: str,
    reference_report: str,
    site_prediction: str = "",
    diagnosis_prediction: str = "",
) -> dict[str, Any]:
    """Core report metrics after excluding non-image-only report facts.

    This intentionally ignores gross size/procedure details, IHC/molecular tests,
    full margin/lymph-node/stage facts, and other information not available from
    H&E WSI ROI images alone. It should be used as the primary metric for
    image-only experiments; full-report similarity remains a secondary metric.
    """
    pred_sections = extract_sections(generated_report)
    ref_sections = extract_sections(reference_report)
    pred_core = {
        "site": site_prediction or pred_sections.get("Specimen/Site", ""),
        "diagnosis": diagnosis_prediction or pred_sections.get("Diagnosis", ""),
        "morphology": _join_nonempty([
            pred_sections.get("Tumor/Lesion Description", ""),
            pred_sections.get("Key Microscopic Findings", ""),
        ]),
        "necrosis_invasion": pred_sections.get("Invasion/Necrosis/Margins", ""),
    }
    ref_core = {
        "site": _image_only_site(ref_sections.get("Specimen/Site", "")),
        "diagnosis": ref_sections.get("Diagnosis", ""),
        "morphology": _image_only_morphology(_join_nonempty([
            ref_sections.get("Tumor/Lesion Description", ""),
            ref_sections.get("Key Microscopic Findings", ""),
        ])),
        "necrosis_invasion": _image_only_necrosis_invasion(ref_sections.get("Invasion/Necrosis/Margins", "")),
    }
    section_weights = {
        "site": 0.20,
        "diagnosis": 0.45,
        "morphology": 0.25,
        "necrosis_invasion": 0.10,
    }
    section_scores = {}
    weighted = []
    for key, weight in section_weights.items():
        score = text_semantic_similarity(pred_core[key], ref_core[key])
        section_scores[key] = {
            **score,
            "weight": weight,
        }
        if score["reference_chars"] > 0 or score["prediction_chars"] > 0:
            weighted.append((weight, score["semantic_similarity"]))
    core_score = sum(w * s for w, s in weighted) / sum(w for w, _s in weighted) if weighted else 0.0
    generated_tokens = len(tokenize(generated_report))
    if generated_tokens < 30:
        core_score = 0.0
        quality_flag = "empty_or_too_short_generated_report"
    else:
        quality_flag = "ok"
    return {
        "metric_version": "image_only_core_v1",
        "core_score": core_score,
        "quality_flag": quality_flag,
        "generated_token_count": generated_tokens,
        "excluded_reference_content": [
            "gross specimen size/weight/procedure details",
            "IHC/ancillary/molecular tests",
            "TNM/stage and most prognostic metadata",
            "surgical margin and lymph-node status unless directly visible in ROI",
        ],
        "core_sections": {
            "prediction": pred_core,
            "reference": ref_core,
        },
        "section_scores": section_scores,
    }


def _join_nonempty(parts: list[str]) -> str:
    return " ".join(part.strip() for part in parts if part and part.strip())


def _image_only_site(text: str) -> str:
    # Keep organ/site words, but remove procedure-heavy details that cannot be
    # inferred from ROI morphology.
    return _filter_sentences(
        text,
        drop_terms=[
            "resection", "excision", "biopsy", "dissection", "margin", "margins",
            "lymph node", "lymph nodes", "molars", "incisors", "procedure",
            "specimen", "including", "with", "and",
        ],
        keep_if_empty=True,
    )


def _image_only_morphology(text: str) -> str:
    return _filter_sentences(
        text,
        drop_terms=[
            "gross", "grossly", "measuring", "measures", "weighing", "weight",
            "cm", "mm", "gram", "g,", "cut surface", "tan", "skin ellipse",
            "procedure", "submitted", "received", "oriented",
        ],
        keep_if_empty=False,
    )


def _image_only_necrosis_invasion(text: str) -> str:
    return _filter_sentences(
        text,
        drop_terms=[
            "margin", "margins", "inked", "lymph node", "lymph nodes", "pn",
            "pt", "stage", "tnm", "0/", "negative for metastasis",
        ],
        keep_terms=["necrosis", "necrotic", "invasion", "invasive", "capsular", "vascular"],
        keep_if_empty=False,
    )


def _filter_sentences(
    text: str,
    drop_terms: list[str],
    keep_terms: list[str] | None = None,
    keep_if_empty: bool = False,
) -> str:
    import re

    if not text:
        return ""
    sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+|;\s+", text) if s.strip()]
    if not sentences:
        sentences = [text.strip()]
    kept = []
    for sent in sentences:
        low = sent.lower()
        if keep_terms and not any(term in low for term in keep_terms):
            continue
        if any(term in low for term in drop_terms):
            continue
        kept.append(sent)
    if kept:
        return " ".join(kept)
    return text.strip() if keep_if_empty else ""
